def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive = []
    prev_bids = []
    opp_pressures = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = None
            if prev:
                bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                req = max(1, float(opp.get('water_requirement', WATER_REQ)))
                opp_pressures.append(float(bid) / req)

    if not alive:
        base = 18.0 if hp > 3 else 42.0
        return max(0, min(budget, base))

    total_players = 1 + len(alive)
    expected_share = supply / float(total_players)
    scarcity = expected_share < WATER_REQ

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_pressure = max(opp_pressures) if opp_pressures else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1
    if day >= 8:
        urgency += 1

    if supply >= 22:
        supply_band = 0
    elif supply >= 18:
        supply_band = 1
    else:
        supply_band = 2

    if scarcity:
        if urgency >= 5:
            bid = max(86.0, highest_prev + 2.5)
        elif urgency >= 3:
            bid = max(72.0, avg_prev + 3.0)
        else:
            bid = min(46.0, max(24.0, avg_prev * 0.55))
    else:
        if urgency >= 5:
            bid = max(74.0, avg_prev + 1.5)
        elif urgency >= 3:
            bid = max(52.0, avg_prev * 0.72)
        else:
            bid = max(18.0, avg_prev * 0.38)

    if highest_prev >= 120:
        if urgency <= 2 and supply_band <= 1:
            bid = min(bid, 34.0)
        elif urgency >= 5:
            bid = max(bid, 92.0)
    elif highest_prev >= 95:
        if urgency <= 2 and not scarcity:
            bid = min(bid, 30.0)
        else:
            bid = max(bid, 58.0)

    if max_pressure >= 8.0 and urgency <= 2 and supply >= 20:
        bid = min(bid, 28.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 35.0
    if urgency >= 5:
        reserve_floor = 0.0

    affordable = max(0.0, budget - reserve_floor)
    if affordable <= 0:
        affordable = budget * 0.5

    bid = min(bid, affordable)
    bid = min(bid, budget)

    if urgency >= 5:
        bid = min(budget, max(bid, 88.0 if scarcity else 70.0))
    elif urgency >= 3:
        bid = min(budget, max(bid, 48.0))

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.3))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else DAILY_SALARY * 0.5

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 0.95)
    elif day_context['supply'] < WATER_REQ * 1.5:
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.6, avg_prev_bid * 1.1))
    else:
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.4, avg_prev_bid * 0.9))

    return float(bid)
